from pathlib import Path
p=Path('app/lume.tsx');s=p.read_text(encoding='utf-8-sig')
s=s.replace('async function act(body:Record<string,unknown>)','async function act(body:Record<string,unknown>,endpoint="/api/lume")').replace("fetch('/api/lume',{method:'POST'","fetch(endpoint,{method:'POST'")
start=s.index(' async function importBackup(');end=s.index('\n function readFile',start)
s=s[:start]+''' async function exportFullBackup(){if(lock.current)return;lock.current=true;setBusy(true);setError('');try{const r=await fetch('/api/lume/backup');if(!r.ok){const d=await r.json() as {error?:string};throw Error(d.error||'Não foi possível exportar.');}const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download='lume-backup-completo.json';a.click();URL.revokeObjectURL(url);}catch(e){setError(e instanceof Error?e.message:'Falha ao exportar.');}finally{lock.current=false;setBusy(false);}}
 async function importBackup(f:File){try{if(f.size>4_000_000)throw Error('Use um backup de até 4 MB.');const b=JSON.parse(await f.text());if(![1,2].includes(b.version)||!Array.isArray(b.decks))throw Error('Use um backup do Lume versão 1 ou 2.');if(!confirm('Restaurar cria cópias dos baralhos. Seus estudos atuais serão mantidos. Continuar?'))return;const restored=await act(b.version===2?b:{action:'importBackup',decks:b.decks},b.version===2?'/api/lume/backup':'/api/lume');if(restored){await refresh();setNotice(b.version===2?'Backup completo restaurado: conteúdo, revisões e conversas preservados.':'Conteúdo importado. As revisões dos novos cartões começam do zero.');}}catch(e){setError(e instanceof Error?e.message:'Backup inválido.');}}
''' + s[end:]
s=s.replace('onClick={exportBackup}><Download size={16}/> Exportar baralhos','onClick={exportBackup}><Download size={16}/> Exportar conteúdo')
s=s.replace('<div className="backup-actions">','<p className="muted backup-help">O backup completo inclui progresso e conversas. A restauração cria cópias dos baralhos.</p><div className="backup-actions"><button className="text-button" disabled={busy} onClick={()=>void exportFullBackup()}><Download size={16}/> Backup completo</button>')
p.write_text(s,encoding='utf-8')
